SELECT CAST(SUM(CASE WHEN LOWER(Batting_hand) LIKE '%right%' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM Player
WHERE SUBSTR(DOB, 1, 4) > 1985;

SELECT CAST(SUM(CASE WHEN LOWER(Batting_Style.Batting_hand) = 'right-hand bat' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM Player
JOIN Batting_Style ON Player.Batting_hand = Batting_Style.Batting_Id;

SELECT p.DOB
