SELECT CAST(SUM(CASE WHEN LOWER(Batting_Style.Batting_hand) LIKE '%left%' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN LOWER(Batting_Style.Batting_hand) LIKE '%right%' THEN 1 ELSE 0 END) AS ratio
